from typing import List
def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    dp = [[float('inf')] * n for _ in range(n)]

    # Initialize the first row and column
    for i in range(n):
        dp[0][i] = grid[0][i]
        dp[i][0] = grid[i][0]

    # Fill the DP table
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    # Backtrack to find the minimum path
    def backtrack(i, j, k):
        if k == 0:
            return []

        res = []
        if i > 0:
            res.append(backtrack(i-1, j, k-1))
        if j > 0:
            res.append(backtrack(i, j-1, k-1))

        return res

    result = backtrack(n-1, n-1, k-1)
    return sorted([grid[i][j] for sublist in result for i, j in enumerate(sublist)])

